input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?zone ?sensor ?name ?ts WHERE {
  ?sensor a brick:ElectricPower_Sensor ;
          brick:hasPoint ?zone .
  ?zone a brick:Zone .
  ?zone rdfs:label ?name .
  FILTER(?zone LIKE "%lighting%")
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT * WHERE {
  ?s ?p ?o .
  FILTER(str(?p) LIKE "%ight%")
} LIMIT 40

